#include <stdio.h>
#include <string.h>
#include <ctype.h>

void to_camel(char *str) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        if (str[i] == '_') {
            str[i] = ' ';
        }
    }
    for (int i = 0; i < len; i++) {
        if (str[i] == ' ') {
            if (i + 1 < len) {
                str[i + 1] = toupper(str[i + 1]);
            }
        }
    }
    for (int i = 0; i < len; i++) {
        if (str[i] == ' ') {
            str[i] = '\0';
        }
    }
}

void to_snake(char *str) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        if (isupper(str[i])) {
            str[i] = tolower(str[i]);
            if (i > 0) {
                str[i - 1] = '_';
            }
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("USAGE\n");
        return 0;
    }
    if (strcmp(argv[1], "to_camel") == 0) {
        to_camel(argv[2]);
        printf("%s\n", argv[2]);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        to_snake(argv[2]);
        printf("%s\n", argv[2]);
    } else {
        printf("INVALID_MODE\n");
    }
    return 0;
}
